import {CalendarDays,Wallet,Store,ArrowRight} from 'lucide-react'
import { useState } from 'react'
import { Link, useParams } from 'react-router-dom'
import { Page,Section,Form,Load,useData,send,Details,Action,Collection,Status,secondary,money,str,date,UploadForm,upload,type Row,type ListData,type Field } from '../../components/workspace/Tools'
const root='/vendors/me';const appRoot='/vendor-applications';const serviceRoot=root+'/services';
const link=(to:string,label:string)=><Link to={to} className={secondary}>{label}</Link>
const reason:Field={key:'reason',label:'Alasan',type:'textarea',required:true}
const locations:Field[]=[{key:'location_type',label:'Jenis lokasi',type:'select',options:[['VERIFICATION_PRIVATE','Verifikasi (privat)'],['OPERATIONAL_PRIVATE','Operasional (privat)'],['PUBLIC_BUSINESS','Usaha (publik)']],required:true},{key:'address_line1',label:'Alamat',required:true},{key:'city',label:'Kota'},{key:'province',label:'Provinsi'},{key:'latitude',label:'Latitude',type:'number',min:-90,max:90,step:'any',required:true},{key:'longitude',label:'Longitude',type:'number',min:-180,max:180,step:'any',required:true}]
export default function VendorHome(){const [clock]=useState(()=>Date.now());const [rev,setRev]=useState(0);const refresh=()=>setRev(n=>n+1);const v=useData<Row>(root,rev),a=useData<Row>(appRoot+'/me',rev);const [doc,setDoc]=useState('KTP');const orders=useData<ListData>(v.data?root+'/bookings?limit=100':null,rev);const services=useData<ListData>(v.data?root+'/services':null,rev);const finance=useData<Row>(v.data?.status==='ACTIVE'?root+'/finance/summary':null,rev);const app=a.data;const path=appRoot+'/'+str(app?.id);const editable=['DRAFT','NEEDS_REVISION'].includes(str(app?.status));return <Page title="Ruang mitra" sub="Daftarkan usaha, kelola layanan, dan pantau pesanan.">{v.loading||a.loading?<p>Memuat profil mitra…</p>:v.data?<><div className="dash-greeting"><div><p className="eyebrow">OPERASIONAL MITRA</p><h1>{str(v.data.public_display_name)}</h1><Status value={v.data.status}/></div><Link to="/mitra/jadwal" className="pp-primary"><CalendarDays size={18}/> Kalender operasional</Link></div><div className="pp-metrics">{[{l:'Total reservasi',n:orders.data?.total??'—',Icon:CalendarDays,to:'/mitra/pesanan'},{l:'Layanan aktif (halaman ini)',n:services.data?.items.filter(x=>x.status==='ACTIVE').length??'—',Icon:Store,to:'/mitra/layanan'},{l:'Saldo tersedia',n:money(finance.data?.available),Icon:Wallet,to:'/mitra/keuangan'}].map(({l,n,Icon,to})=><Link key={l} to={to} className="pp-metric"><span><Icon size={22}/></span><div><small>{l}</small><strong>{n}</strong></div></Link>)}</div><div className="pp-dashboard-grid"><Section title="Agenda operasional"><Load {...orders}>{orders.data?.items.some(b=>['CONFIRMED','IN_PROGRESS'].includes(str(b.status)))?orders.data.items.filter(b=>['CONFIRMED','IN_PROGRESS'].includes(str(b.status))).sort((a,b)=>str(a.scheduled_start_at).localeCompare(str(b.scheduled_start_at))).slice(0,7).map(b=><Link key={str(b.id)} to={'/mitra/pesanan/'+b.id} className="pp-agenda-row"><small>{date(b.scheduled_start_at)}</small><div><strong>{str(b.customer_display_name)||'Customer'}</strong><small>{str(b.package_name_snapshot)} · {str(b.pet_name)}</small></div><Status value={b.status}/></Link>):<p className="text-sm text-slate-500">Belum ada pesanan.</p>}</Load><Link className="pp-secondary" to="/mitra/pesanan">Semua pesanan <ArrowRight size={16}/></Link></Section><Section title="Jadwal tujuh hari"><Load {...orders}>{Array.from({length:7},(_,i)=>{const day=new Date(clock+7*3600000+i*86400000).toISOString().slice(0,10);const count=orders.data?.items.filter(b=>['CONFIRMED','IN_PROGRESS'].includes(str(b.status))&&b.scheduled_start_at&&new Date(Date.parse(str(b.scheduled_start_at))+7*3600000).toISOString().slice(0,10)===day).length??0;return <div className="pp-week-day" key={day}><span>{new Date(day+'T00:00:00Z').toLocaleDateString('id-ID',{weekday:'short',day:'numeric',month:'short',timeZone:'UTC'})}</span><strong>{count} reservasi</strong></div>})}</Load><p className="text-xs text-slate-500">Berdasarkan maksimal 100 reservasi yang dimuat.</p><Link className="pp-secondary" to="/mitra/jadwal">Lihat kalender <ArrowRight size={16}/></Link></Section></div><Load {...a}>{app&&<Section title="Pengajuan verifikasi"><Details row={app} keys={['id','status','declared_identity_name','business_name','representative_name','terms_version','terms_accepted_at','decision_reason']}/>{editable&&<><Form key={rev} fields={[{key:'declared_identity_name',label:'Nama sesuai identitas',required:true},{key:'business_name',label:'Nama badan usaha',nullable:true},{key:'representative_name',label:'Nama perwakilan',nullable:true}]} initial={app} submit="Simpan identitas" onSubmit={async b=>{await send(path,'PATCH',b);refresh()}}/><div className="border-t border-slate-100 pt-4"><p className="mb-2 text-sm text-slate-600">Masukkan versi persyaratan yang telah Anda baca dan setujui. Untuk pengujian lokal, versi demo sebelumnya adalah DEMO_V1. Tidak ada naskah syarat aktual di API.</p><Form fields={[{key:'terms_version',label:'Versi persyaratan',required:true}]} submit="Setujui persyaratan" onSubmit={async b=>{if(!window.confirm('Saya telah membaca dan menyetujui persyaratan versi ini.'))throw new Error('Persetujuan dibatalkan.');await send(path+'/terms/accept','POST',b);refresh()}}/></div><label className="block text-sm font-semibold">Jenis dokumen<select className="mt-2 block w-full rounded-xl border border-slate-200 p-3" value={doc} onChange={e=>setDoc(e.target.value)}>{['KTP','VERIFICATION_SELFIE','NIB_BUSINESS_EVIDENCE','PROFESSIONAL_CREDENTIAL','PORTFOLIO'].map(x=><option key={x}>{x}</option>)}</select></label><UploadForm label="Dokumen verifikasi (gunakan file dummy saat demo lokal)" run={async f=>{const m=await upload(path+'/documents/upload-intent',f);await send(path+'/documents','POST',{document_type:doc,media_object_id:m});refresh()}}/></>}<h3 className="font-bold">Dokumen terdaftar</h3><Collection path={path+'/documents'} revision={rev}>{d=><Details row={d} keys={['id','document_type','status','review_reason','verified_at']}/>}</Collection>{editable&&<><p className="text-sm text-slate-600">Sebelum mengajukan: lengkapi KTP, selfie (dan NIB untuk badan usaha), lokasi, rekening, minimal satu layanan dengan paket, aturan hewan dan jadwal.</p><Action label="Ajukan verifikasi" confirm run={async()=>{await send(path+'/submit');refresh()}}/></>}</Section>}</Load></>:v.error==='Vendor not found.'?<Section title="Mulai menjadi mitra"><Form fields={[{key:'vendor_type',label:'Jenis mitra',type:'select',options:[['INDIVIDUAL','Perorangan'],['BUSINESS','Badan usaha']],required:true},{key:'public_display_name',label:'Nama toko',required:true}]} submit="Buat pengajuan" onSubmit={async b=>{await send(appRoot,'POST',b);refresh()}}/></Section>:<p role="alert" className="text-red-700">{v.error}</p>}</Page>}
export function VendorLocations(){const [rev,setRev]=useState(0);const a=useData<Row>(appRoot+'/me');const editable=['DRAFT','NEEDS_REVISION'].includes(str(a.data?.status));const refresh=()=>setRev(n=>n+1);return <Page title="Lokasi mitra" sub="Lokasi privat tidak ditampilkan pada katalog publik.">{link('/mitra','Kembali ke ruang mitra')}{editable&&<Section title="Tambah lokasi"><Form fields={locations} submit="Simpan lokasi" onSubmit={async b=>{await send(root+'/locations','POST',b);refresh()}}/></Section>}<Collection path={root+'/locations'} revision={rev}>{l=><div className="space-y-3"><Details row={l}/>{editable&&<><details><summary className="cursor-pointer text-[#0F766E]">Edit lokasi</summary><Form fields={locations.filter(f=>f.key!=='location_type')} initial={l} submit="Simpan perubahan" onSubmit={async b=>{await send(root+'/locations/'+l.id,'PATCH',b);refresh()}}/></details><Action label="Hapus lokasi" danger confirm run={async()=>{await send(root+'/locations/'+l.id,'DELETE');refresh()}}/></>}</div>}</Collection></Page>}
function serviceFields(l:Row[]):Field[]{return [{key:'name',label:'Nama layanan',required:true},{key:'category_code',label:'Kode kategori (contoh GROOMING)',required:true},{key:'description',label:'Deskripsi',type:'textarea',nullable:true},{key:'delivery_mode',label:'Mode layanan',type:'select',options:[['AT_VENDOR','Di lokasi mitra'],['AT_CUSTOMER','Ke rumah customer']],required:true},{key:'origin_vendor_location_id',label:'Lokasi asal operasional',type:'select',options:l.filter(x=>x.location_type!=='VERIFICATION_PRIVATE').map(x=>[str(x.id),str(x.address_line1)]),required:true},{key:'service_radius_meters',label:'Radius ke rumah (meter)',type:'number',min:1,nullable:true},{key:'minimum_notice_minutes',label:'Minimal pemberitahuan (menit)',type:'number',min:0,initial:60,required:true},{key:'buffer_after_minutes',label:'Buffer setelah layanan (menit)',type:'number',min:0,initial:30,required:true},{key:'base_capacity',label:'Kapasitas',type:'number',min:1,initial:1,required:true}]}
export function VendorServices(){const [rev,setRev]=useState(0);const l=useData<ListData>(root+'/locations');return <Page title="Layanan mitra" sub="Buat dan atur katalog layanan yang pelanggan dapat pesan.">{link('/mitra','Kembali ke ruang mitra')}<Section title="Buat layanan"><details><summary className="font-semibold text-teal-700">+ Tambah layanan baru</summary><div className="mt-4"><Load {...l}><Form fields={serviceFields(l.data?.items??[])} submit="Buat layanan" onSubmit={async b=>{await send(serviceRoot,'POST',b);setRev(n=>n+1)}}/></Load></div></details></Section><Collection path={serviceRoot} revision={rev}>{s=><div className="flex flex-wrap items-center gap-3"><div className="flex-1"><h3 className="font-bold text-lg">{str(s.name)}</h3><p className="text-sm text-slate-500">{str(s.category_code)} · {str(s.delivery_mode)}</p></div><Status value={s.status}/>{link('/mitra/layanan/'+s.id,'Konfigurasi')}</div>}</Collection></Page>}
const packageFields:Field[]=[{key:'name',label:'Nama paket',required:true},{key:'description',label:'Deskripsi',type:'textarea',nullable:true},{key:'duration_minutes',label:'Durasi (menit)',type:'number',min:1,required:true},{key:'price_amount',label:'Harga (IDR)',type:'number',min:1,required:true},{key:'currency',label:'Mata uang',type:'select',options:[['IDR','IDR']],initial:'IDR',required:true}]
const windowFields:Field[]=[{key:'starts_at',label:'Mulai (WIB)',type:'datetime-local',required:true},{key:'ends_at',label:'Selesai (WIB)',type:'datetime-local',required:true}]
const ruleFields:Field[]=[{key:'accepted_species',label:'Jenis hewan (pisahkan koma, CAT,DOG)',type:'csv',required:true},{key:'accepted_size_codes',label:'Ukuran (SMALL,MEDIUM,LARGE)',type:'csv',nullable:true},{key:'accepts_reactive',label:'Terima hewan reaktif',type:'bool',initial:false,required:true},{key:'accepts_aggressive_history',label:'Terima riwayat agresif',type:'bool',initial:false,required:true},{key:'context_notes',label:'Catatan aturan',type:'textarea',nullable:true}]
export function VendorServiceDetail(){const {id}=useParams();const path=serviceRoot+'/'+id;const [rev,setRev]=useState(0),[tab,setTab]=useState("identity");const refresh=()=>setRev(n=>n+1);const list=useData<ListData>(serviceRoot+'?limit=100',rev),l=useData<ListData>(root+'/locations'),r=useData<Row>(path+'/pet-rules',rev);const s=list.data?.items.find(x=>x.id===id);return <Page title={str(s?.name)||'Konfigurasi layanan'} sub="Atur paket, asal layanan, aturan hewan, jadwal dan kapasitas.">{link('/mitra/layanan','Semua layanan')}<Load loading={list.loading||l.loading} error={list.error||l.error}>{s&&<><div role="group" aria-label="Pengaturan layanan" className="flex flex-wrap gap-2 rounded-xl border border-slate-200 bg-white p-2">{[['identity','Informasi'],['packages','Paket'],['rules','Aturan hewan'],['availability','Jadwal'],['capacity-overrides','Kapasitas khusus']].map(([value,label])=><button key={value} type="button" aria-pressed={tab===value} className={'rounded-lg px-4 py-2 text-sm font-semibold '+(tab===value?'bg-[#0F766E] text-white':'text-slate-600 hover:bg-slate-50')} onClick={()=>setTab(value)}>{label}</button>)}</div>{tab==='identity'&&<Section title="Identitas layanan"><Status value={s.status}/><Form key={rev} fields={serviceFields(l.data?.items??[]).filter(f=>['DRAFT','INACTIVE'].includes(str(s.status))||!['delivery_mode','origin_vendor_location_id'].includes(f.key))} initial={s} submit="Simpan layanan" onSubmit={async b=>{await send(path,'PATCH',b);refresh()}}/><Action label={s.status==='ACTIVE'?'Nonaktifkan layanan':'Aktifkan layanan'} confirm run={async()=>{await send(path+(s.status==='ACTIVE'?'/deactivate':'/activate'));refresh()}}/></Section>}{tab==='packages'&&<Section title="Paket layanan"><Form fields={packageFields} submit="Tambah paket" onSubmit={async b=>{await send(path+'/packages','POST',b);refresh()}}/><Collection path={path+'/packages'} revision={rev}>{p=><div className="space-y-3"><h3 className="font-bold">{str(p.name)} · {money(p.price_amount)}</h3><p className="text-sm">{p.is_active?'Aktif':'Nonaktif'} · {str(p.duration_minutes)} menit</p><details><summary className="cursor-pointer text-[#0F766E]">Edit paket</summary><Form fields={packageFields} initial={p} submit="Simpan" onSubmit={async b=>{await send(path+'/packages/'+p.id,'PATCH',b);refresh()}}/></details><Action label={p.is_active?'Nonaktifkan paket':'Aktifkan paket'} run={async()=>{await send(path+'/packages/'+p.id+(p.is_active?'/deactivate':'/activate'));refresh()}}/></div>}</Collection></Section>}{tab==='rules'&&<Section title="Aturan hewan"><Load {...r}><Form key={rev} fields={ruleFields} initial={{...r.data,accepted_species:r.data?.accepted_species_json,accepted_size_codes:r.data?.accepted_size_codes_json}} submit="Simpan aturan" onSubmit={async b=>{await send(path+'/pet-rules','PUT',{...b,deterministic_restrictions:r.data?.deterministic_restrictions_json??[]});refresh()}}/></Load></Section>}{(['availability','capacity-overrides'] as const).filter(kind=>tab===kind).map(kind=>{const fields:Field[]=kind==='availability'?windowFields:[...windowFields,{key:'capacity',label:'Kapasitas khusus',type:'number',min:0,required:true}];return <Section key={kind} title={kind==='availability'?'Jadwal operasional':'Override kapasitas'}><Link to="/mitra/jadwal" className="text-sm font-semibold text-teal-700">Lihat kalender operasional →</Link><Form fields={fields} submit="Tambah jadwal" onSubmit={async b=>{await send(path+'/'+kind,'POST',b);refresh()}}/><Collection path={path+'/'+kind} revision={rev}>{w=><div className="space-y-3"><Details row={w} keys={['id','starts_at','ends_at','capacity']}/><details><summary className="cursor-pointer text-[#0F766E]">Edit jadwal</summary><Form initial={w} fields={fields} submit="Simpan" onSubmit={async b=>{await send(path+'/'+kind+'/'+w.id,'PATCH',b);refresh()}}/></details><Action label="Hapus jadwal" danger confirm run={async()=>{await send(path+'/'+kind+'/'+w.id,'DELETE');refresh()}}/></div>}</Collection></Section>})}</>}</Load></Page>}
export function PayoutAccounts(){const [rev,setRev]=useState(0),[challenge,setChallenge]=useState(''),[verified,setVerified]=useState(false);const accounts=useData<ListData>(root+'/payout-accounts',rev);const existing=accounts.data?.items.some(x=>x.is_active);return <Page title="Rekening pencairan" sub="Perubahan rekening aktif memerlukan password dan OTP sensitif.">{link('/mitra','Kembali ke ruang mitra')}<Section title="Rekening terdaftar"><Load {...accounts}>{accounts.data?.items.map(x=><Details key={str(x.id)} row={x}/>)}</Load></Section>{existing&&<Section title="Verifikasi perubahan"><Form fields={[{key:'password',label:'Password akun',type:'password',required:true}]} submit="Verifikasi password" onSubmit={async b=>{setVerified(false);setChallenge('');await send('/auth/reauth','POST',b);const c=await send('/auth/sensitive-otp/request','POST',{purpose:'PAYOUT_ACCOUNT_CHANGE'});setChallenge(str(c.challenge_id))}}/>{challenge&&<Form fields={[{key:'code',label:'OTP perubahan rekening',required:true}]} submit="Verifikasi OTP" onSubmit={async b=>{await send('/auth/sensitive-otp/verify','POST',{...b,challenge_id:challenge,purpose:'PAYOUT_ACCOUNT_CHANGE'});setVerified(true)}}/>}</Section>}{!accounts.loading&&!accounts.error&&(!existing||verified)&&<Section title={existing?'Ganti rekening':'Tambah rekening'}><Form fields={[{key:'bank_code',label:'Kode bank',required:true},{key:'account_holder_name',label:'Nama pemilik',required:true},{key:'account_number',label:'Nomor rekening',required:true}]} submit="Simpan rekening" onSubmit={async b=>{await send(root+'/payout-accounts','POST',b);setVerified(false);setChallenge('');setRev(n=>n+1)}}/></Section>}</Page>}
export function VendorFinance(){const s=useData<Row>(root+'/finance/summary');const [tab,setTab]=useState('settlements');return <Page title="Keuangan mitra" sub="Saldo dan riwayat pencairan berdasarkan ledger backend.">{link('/mitra','Kembali ke ruang mitra')}<Load {...s}>{s.data&&<div className="grid gap-3 sm:grid-cols-3">{['pending','hold','available','allocated','settled','reversed'].map((k,i)=><Section key={k} title={['Menunggu layanan','Ditahan','Tersedia','Dialokasikan','Dicairkan','Dibalik'][i]}><p className="text-2xl font-black text-[#0F766E]">{money(s.data?.[k])}</p></Section>)}</div>}</Load><div className="flex gap-2"><button className={secondary} onClick={()=>setTab('settlements')}>Settlement</button><button className={secondary} onClick={()=>setTab('payouts')}>Payout</button></div><Collection key={tab} path={root+'/'+tab}>{x=><div className="space-y-3"><Details row={x}/>{tab==='payouts'&&link('/mitra/payout/'+x.id,'Detail payout')}</div>}</Collection><Section title="Tanggapi klaim pembatalan"><Claim/></Section></Page>}
function Claim(){return <Form fields={[{key:'id',label:'ID klaim dari customer/admin',required:true},{key:'response',label:'Tanggapan',type:'select',options:[['ADMIT','Akui'],['DENY','Tolak']],required:true},reason]} submit="Kirim tanggapan" onSubmit={b=>send(root+'/cancellation-claims/'+encodeURIComponent(str(b.id))+'/respond','POST',{response:b.response,reason:b.reason})}/>}
// Details for payout history can be loaded using the ID returned by API.
export function PayoutDetail(){const {id}=useParams();const r=useData<Row>(root+'/payouts/'+id);return <Page title="Detail payout" sub="Alokasi dan status pencairan."><Load {...r}>{r.data&&<Section title="Pencairan"><Details row={r.data}/></Section>}</Load></Page>}
